  primary: '#10B981', // Emerald 500
  secondary: '#3B82F6', // Blue 500
  accent: '#EF4444', // Red 500
  bg: '#1F2937', // Gray 800
  text: '#F3F4F6', // Gray 100
  textDim: '#9CA3AF', // Gray 400
};

// --- Helper Components ---

/**
 * Displays text with a typewriter or fade-in effect.
 */
const StepText: React.FC<StepTextProps> = ({ text, frame, startFrame, endFrame, style }) => {
  const opacity = interpolate(frame, [startFrame, startFrame + 15], [0, 1], {
    extrapolateRight: 'clamp',
  });

  // Fade out if endFrame is provided
  const finalOpacity = endFrame 
    ? interpolate(frame, [endFrame - 15, endFrame], [opacity, 0], { extrapolateLeft: 'clamp' })
    : opacity;

  return (
    <div
      style={{
        opacity: finalOpacity,
        fontFamily: 'Arial, sans-serif',
        fontSize: 32,
        color: COLORS.text,
        textAlign: 'center',
        whiteSpace: 'pre-line',
        ...style,
      }}
    >
      {text}
    </div>
