/**
 * Geometric component to render the triangle and optional squares.
 * Uses SVG for precise geometric rendering.
 */
const PythagoreanVisual: React.FC<TriangleProps> = ({
  width,
  height,
  a,
  b,
  c,
  colorA,
  colorB,
  colorC,
  showSquares = false,
  squareProgress = 0,
  showLabels = true,
  labelA = 'a',
  labelB = 'b',
  labelC = 'c',
}) => {
  // Scale factor to fit triangle in view while maintaining aspect ratio
  // Assuming a 3-4-5 triangle base, we scale it to fit roughly 60% of height
  const scale = Math.min(width, height) / 8; 

  // Coordinates calculation (Right angle at bottom-left relative to triangle center)
  // Point A (Bottom, Right angle): (0, b)
  // Point B (Top): (0, 0)
  // Point C (Right): (a, b)
  // We will center this shape in the SVG

  const triA = a * scale;
  const triB = b * scale;
  const triC = c * scale;

  // Offsets to center the triangle + squares
  const maxW = triA + triB; // Rough bounding box
  const maxH = triB + triA;
  const offsetX = (width - maxW) / 2;
  const offsetY = (height - maxH) / 2;

  // Triangle Points
  // P1: Top (0,0) -> P2: Bottom-Right (a, 0) -> P3: Bottom-Left (0, b)
  // Let's orient it: Right angle at bottom-left.
  // x=0, y=b (Right Angle)
  // x=a, y=b (Bottom Right)
  // x=0, y=0 (Top Left)

  const pRightAngle = { x: offsetX, y: offsetY + triB };
  const pBottom = { x: offsetX + triA, y: offsetY + triB };
  const pTop = { x: offsetX, y: offsetY };

  return (
    <svg width={width} height={height} style={{ overflow: 'visible' }}>
      <defs>
        <marker id="arrow" markerWidth="10" markerHeight="10" refX="5" refY="5" orient="auto">
          <path d="M0,0 L0,10 L10,5 z" fill={COLORS.textDim} />
        </marker>
      </defs>

      {/* Square on A (Bottom Side) */}
      {showSquares && (
        <g opacity={squareProgress}>
          <rect
            x={pRightAngle.x}
            y={pRightAngle.y}
            width={triA}
            height={triA}
            fill={colorA}
            fillOpacity={0.3}
            stroke={colorA}
            strokeWidth={4}
          />
          <text
            x={pRightAngle.x + triA / 2}
            y={pRightAngle.y + triA / 2 + 10}
            fill="white"
            fontSize="24"
            textAnchor="middle"
            fontWeight="bold"
          >
            a²
          </text>
        </g>
      )}

      {/* Square on B (Left Side) */}
      {showSquares && (
        <g opacity={squareProgress}>
          <rect
            x={pRightAngle.x - triB}
            y={pRightAngle.y - triB}
            width={triB}
            height={triB}
            fill={colorB}
            fillOpacity={0.3}
            stroke={colorB}
            strokeWidth={4}
          />
          <text
            x={pRightAngle.x - triB / 2}
            y={pRightAngle.y - triB / 2 + 10}
            fill="white"
            fontSize="24"
            textAnchor="middle"
            fontWeight="bold"
          >
            b²
          </text>
        </g>
      )}

      {/* Square on C (Hypotenuse) - Rotated */}
      {showSquares && (
        <g opacity={squareProgress}>
           {/* 
             To draw square on hypotenuse, we need rotation.
             Angle is atan2(b, a).
             Center of hypotenuse is (a/2, b/2) relative to right angle.
             This is complex in raw SVG without transforms, simplified approach:
             Just draw the triangle first, then overlay the square logic if needed.
             For this demo, we will draw the square attached to the hypotenuse.
           */}
           <path
             d={`
                M ${pTop.x} ${pTop.y}
                L ${pTop.x - triB} ${pTop.y + triA}
                L ${pBottom.x - triB} ${pBottom.y + triA}
                L ${pBottom.x} ${pBottom.y}
                Z
             `}
             fill={colorC}
             fillOpacity={0.3}
             stroke={colorC}
             strokeWidth={4}
           />
           <text
             x={(pTop.x + pBottom.x) / 2 - triB/2}
             y={(pTop.y + pBottom.y) / 2 + triA/2 + 10}
             fill="white"
             fontSize="24"
             textAnchor="middle"
             fontWeight="bold"
           >
             c²
           </text>
        </g>
      )}

      {/* The Triangle */}
      <polygon
        points={`${pTop.x},${pTop.y} ${pBottom.x},${pBottom.y} ${pRightAngle.x},${pRightAngle.y}`}
        fill="none"
        stroke="white"
        strokeWidth={6}
      />

      {/* Right Angle Marker */}
      <path
        d={`M ${pRightAngle.x + 30} ${pRightAngle.y} L ${pRightAngle.x + 30} ${pRightAngle.y - 30} L ${pRightAngle.x} ${pRightAngle.y - 30}`}
        stroke="white"
        strokeWidth={2}
        fill="none"
      />

      {/* Labels */}
      {showLabels && (
        <>
          {/* Label A */}
          <text
            x={pRightAngle.x + triA / 2}
            y={pRightAngle.y + 40}
            fill={colorA}
            fontSize="28"
            textAnchor="middle"
            fontWeight="bold"
          >
            {labelA}
          </text>
          {/* Label B */}
          <text
            x={pRightAngle.x - 40}
            y={pRightAngle.y - triB / 2}
            fill={colorB}
            fontSize="28"
            textAnchor="middle"
            fontWeight="bold"
          >
            {labelB}
          </text>
          {/* Label C */}
          <text
            x={(pTop.x + pBottom.x) / 2 + 20}
            y={(pTop.y + pBottom.y) / 2 - 20}
            fill={colorC}
            fontSize="28"
            textAnchor="middle"
            fontWeight="bold"
          >
            {labelC}
          </text>
        </>
      )}
    </svg>
  );
};

