import React, { useMemo, useState, useCallback, useEffect } from 'react';
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Sequence,
  Audio,
  staticFile,
} from 'remotion';
import { z } from 'zod';

// --- Configuration & Constants ---

const COLORS = {
  background: '#111827', // Gray 900
  text: '#F3F4F6', // Gray 100
  primary: '#3B82F6', // Blue 500
  secondary: '#F59E0B', // Amber 500
  accent: '#10B981', // Emerald 500
  grid: '#374151', // Gray 700
  axis: '#9CA3AF', // Gray 400
  error: '#EF4444', // Red 500
};

const MATH = {
  sin: (x: number) => Math.sin(x),
  cos: (x: number) => Math.cos(x),
  exp: (x: number) => Math.exp(x),
  // Taylor Series for sin(x) around 0: x - x^3/3! + x^5/5! ...
  taylorSin: (x: number, order: number) => {
    let result = 0;
    for (let n = 0; n <= order; n++) {
      const k = 2 * n + 1; // 1, 3, 5, 7...
      const sign = n % 2 === 0 ? 1 : -1;
      const factorial = (num: number) => (num <= 1 ? 1 : num * factorial(num - 1));
      result += sign * Math.pow(x, k) / factorial(k);
    }
    return result;
  },
};

// --- Types & Interfaces ---

interface Point {
  x: number;
  y: number;
}

interface GraphProps {
  width: number;
  height: number;
  func: (x: number) => number;
  range: number;
  color: string;
  strokeWidth?: number;
  label?: string;
}

// --- Helper Components ---

/**
 * Formula Component
 * Displays mathematical formulas with specific styling.
 */
const Formula: React.FC<{
  children: React.ReactNode;
  style?: React.CSSProperties;
  highlight?: boolean;
}> = ({ children, style, highlight = false }) => {
  return (
    <div
      style={{
        fontFamily: 'Georgia, serif',
        fontSize: 48,
        color: highlight ? COLORS.secondary : COLORS.text,
        textAlign: 'center',
        marginBottom: 20,
        textShadow: highlight ? '0 0 20px rgba(245, 158, 11, 0.5)' : 'none',
        ...style,
      }}
    >
      {children}
    </div>
  );
};

/**
 * MathGraph Component
 * Renders a mathematical function on a coordinate system using SVG.
 */
const MathGraph: React.FC<GraphProps> = ({
  width,
  height,
  func,
  range,
  color,
  strokeWidth = 3,
  label,
}) => {
  // Memoize path calculation to avoid re-renders
  const pathData = useMemo(() => {
    const points: Point[] = [];
    const step = (range * 2) / 200; // Resolution

    for (let x = -range; x <= range; x += step) {
      const y = func(x);
      // Map math coordinates to screen coordinates
      // Screen X: 0 to width. Math X: -range to range
      // Screen Y: height to 0. Math Y: -1.5 to 1.5 (approx)

      const screenX = ((x + range) / (range * 2)) * width;
      // Scale Y assuming range is roughly -2 to 2 for visualization
      const screenY = height / 2 - (y * height) / 4; 

      points.push({ x: screenX, y: screenY });
    }

    if (points.length === 0) return '';

    // Start path
    let d = `M ${points[0].x.toFixed(1)} ${points[0].y.toFixed(1)}`;

    // Connect points
    for (let i = 1; i < points.length; i++) {
      d += ` L ${points[i].x.toFixed(1)} ${points[i].y.toFixed(1)}`;
    }

    return d;
  }, [func, range, width, height]);

  return (
    <svg width={width} height={height} style={{ overflow: 'visible' }}>
      {/* Grid Lines */}
      <line x1={width / 2} y1={0} x2={width / 2} y2={height} stroke={COLORS.grid} strokeWidth={1} />
      <line x1={0} y1={height / 2} x2={width} y2={height / 2} stroke={COLORS.grid} strokeWidth={1} />

      {/* Function Curve */}
      <path d={pathData} fill="none" stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" />

      {/* Label */}
      {label && (
        <text
          x={width - 20}
          y={height / 2 - 50}
          fill={color}
          fontSize={24}
          fontFamily="sans-serif"
          textAnchor="end"
          fontWeight="bold"
        >
          {label}
        </text>
      )}
    </svg>
  );
};

