  // 0: Nothing, 1: Constant, 2: Linear, 3: Quadratic
  const getOrder = useCallback(() => {
    if (frame < step1) return 0;
    if (frame < step2) return 1;
    if (frame < step3) return 2;
    return 3;
  }, [frame, step1, step2, step3]);

  const order = getOrder();

  // Define the target function (sin(x)) and approximations
  // Center a = 0
  const targetFunc = (x: number) => MATH.sin(x);

  const approxFunc = (x: number) => {
    if (order === 0) return 0; // Start at 0
    if (order === 1) return 0; // Constant f(0) = 0
    if (order === 2) return x; // Linear f'(0)x = x
    return x; // Quadratic f''(0)x^2/2 = 0 (sin is odd, so quadratic term is 0, effectively same as linear for sin)
    // Note: For sin(x), the quadratic term is 0. To make visualization interesting, 
    // we usually jump to cubic. Let's adjust logic for visual flair.
  };

  // Custom logic for Sin(x) Taylor visualization
  // Order 0: 0
  // Order 1: x
