    if (order === 0) return 0;
    if (order === 1) return x; // Linear
    if (order === 2) return x; // Still Linear (Quadratic term is 0)
    if (order === 3) return x - Math.pow(x, 3) / 6; // Cubic
    return x - Math.pow(x, 3) / 6;
  };

  const labels = ["Start", "Constant", "Linear (Slope)", "Cubic (Curvature)"];
